/* ---------- Certificates: card stack ---------- */
/* Certificates: fly-away infinite card stack (certificates with images come first) */
const D = [...C.filter((c) => c[2]), ...C.filter((c) => !c[2])].map(([t, o, f]) => {
  const a = [].concat(f || []);
  return { t, o, src: a.length ? `./images/${a[0]}` : "", c: a.slice(1), ok: !!a.length };
});
const N = D.length,
  stk = $("#stk"),
  inf = $("#inf"),
  dts = $("#dts"),
  fs = $("#fs"),
  lock = { on: false };
const face = (d) =>
  `<div class="cf"><span class="cfi">${d.o}</span><b>${d.t}</b><span class="cfs"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg></span></div>`;
stk.innerHTML = D.map(
  (d, i) =>
    `<figure class="cd" data-p="0">${d.ok ? `<img src="${d.src}" alt="${d.t}, ${d.o}" draggable="false" loading="${i < 4 ? "eager" : "lazy"}">` : face(d)}</figure>`,
).join("");
dts.innerHTML = D.map((d, i) => `<button aria-label="Show ${d.t}" data-i="${i}"></button>`).join(
  "",
);
const cards = [...stk.children];
let cur = 0;
function layout() {
  cards.forEach((c, i) => {
    const p = (i - cur + N) % N;
    c.dataset.p = Math.min(p, 4);
    c.setAttribute("aria-hidden", p !== 0);
  });
  [...dts.children].forEach((b, i) => b.classList.toggle("on", i === cur));
}
function paint() {
  $("#cn1").textContent = String(cur + 1).padStart(2, "0");
  $("#cn2").textContent = "/ " + String(N).padStart(2, "0");
  $("#ci").textContent = D[cur].o;
  $("#ct").textContent = D[cur].t;
  $("#fb").hidden = !D[cur].ok;
}
function swap() {
  clearTimeout(swap.h);
  inf.classList.add("out");
  swap.h = setTimeout(() => {
    paint();
    inf.classList.remove("out");
  }, 480);
}
function go(d) {
  if (lock.on) return;
  lock.on = true;
  const old = cards[cur];
  cur = (cur + d + N) % N;
  if (d > 0) old.classList.add("fly");
  layout();
  swap();
  setTimeout(
    () => {
      old.classList.remove("fly");
      lock.on = false;
    },
    d > 0 ? 1150 : 800,
  );
}
function jump(i) {
  if (lock.on || i === cur) return;
  lock.on = true;
  cur = i;
  layout();
  swap();
  setTimeout(() => {
    lock.on = false;
  }, 800);
}
stk.addEventListener(
  "error",
  (e) => {
    if (e.target.tagName !== "IMG") return;
    const f = e.target.closest(".cd"),
      i = cards.indexOf(f);
    if (D[i].c.length) {
      D[i].src = `./images/${D[i].c.shift()}`;
      e.target.src = D[i].src;
      return;
    }
    D[i].ok = false;
    f.innerHTML = face(D[i]);
    paint();
  },
  true,
);
layout();
paint();
let ct = null,
  ht = null;
stk.addEventListener("click", () => {
  clearTimeout(ct);
  ct = setTimeout(() => go(1), 250);
});
stk.addEventListener("dblclick", () => {
  clearTimeout(ct);
  clearTimeout(ht);
  openFS(cur);
});
stk.addEventListener("pointerenter", (e) => {
  if (e.pointerType !== "mouse") return;
  clearTimeout(ht);
  ht = setTimeout(() => go(1), 220);
});
stk.addEventListener("pointerleave", () => clearTimeout(ht));
stk.addEventListener("pointerdown", () => clearTimeout(ht));
stk.addEventListener("keydown", (e) => {
  if (e.key === "Enter" || e.key === " " || e.key === "ArrowRight") {
    e.preventDefault();
    go(1);
  } else if (e.key === "ArrowLeft") {
    e.preventDefault();
    go(-1);
  }
});
$("#fb").onclick = () => openFS(cur);
dts.onclick = (e) => {
  const b = e.target.closest("button");
  if (b) jump(+b.dataset.i);
};

