/* ---------- Pixel hero animation ---------- */
/* Pixel hero: typing loop, hover = look, long hover = hello */
(() => {
  const sc = $("#sc");
  if (!sc) return;
  const F = [...sc.querySelectorAll(".f")],
    T = [0, 1, 2, 1],
    rm = matchMedia("(prefers-reduced-motion:reduce)").matches;
  let i = 0,
    st = "type",
    hold = null;
  const set = (s) => {
    st = s;
    sc.dataset.s = s;
    F.forEach((f, j) =>
      f.classList.toggle("on", j === (s === "type" ? T[i] : s === "look" ? 3 : 4)),
    );
  };
  const enter = () => {
      clearTimeout(hold);
      set("look");
      hold = setTimeout(() => set("talk"), 1500);
    },
    leave = () => {
      clearTimeout(hold);
      set("type");
    };
  if (rm) {
    set("talk");
    return;
  }
  (function tick() {
    if (st === "type") {
      i = (i + 1) % 4;
      set("type");
    }
    setTimeout(tick, 110 + Math.random() * 80);
  })();
  sc.addEventListener("pointerenter", (e) => {
    if (e.pointerType === "mouse") enter();
  });
  sc.addEventListener("pointerleave", (e) => {
    if (e.pointerType === "mouse") leave();
  });
  sc.addEventListener("pointerdown", (e) => {
    if (e.pointerType !== "mouse") enter();
  });
  addEventListener("pointerup", (e) => {
    if (e.pointerType !== "mouse" && st !== "type") leave();
  });
  sc.addEventListener("focus", enter);
  sc.addEventListener("blur", leave);
  if (matchMedia("(hover:none)").matches)
    setTimeout(() => {
      enter();
      setTimeout(leave, 4500);
    }, 3000);
})();